import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Content Search","description":"","frontmatter":{},"headers":[{"level":2,"title":"Getting started","slug":"getting-started","link":"#getting-started","children":[]},{"level":2,"title":"What gets indexed","slug":"what-gets-indexed","link":"#what-gets-indexed","children":[]},{"level":2,"title":"Searching","slug":"searching","link":"#searching","children":[]},{"level":2,"title":"Clearing and rebuilding","slug":"clearing-and-rebuilding","link":"#clearing-and-rebuilding","children":[]},{"level":2,"title":"Tips","slug":"tips","link":"#tips","children":[]}],"relativePath":"user-guide/content-search.md","filePath":"user-guide/content-search.md","lastUpdated":1791258065000}`),a={name:`user-guide/content-search.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="content-search" tabindex="-1">Content Search <a class="header-anchor" href="#content-search" aria-label="Permalink to “Content Search”">​</a></h1><p>The Content Search plugin searches the text inside your local documents. It runs in the background and works alongside Lertaro&#39;s regular filename search.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h2><p>Open <strong>Settings → Plugins → Content Search → Configure</strong>, set at least one monitored folder, then save. The default trigger keyword is <code>cs</code>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cs project plan</span></span></code></pre></div><p>The keyword must be followed by a space. Replace <code>cs</code> with another keyword in the plugin settings if it conflicts with your workflow.</p><h2 id="what-gets-indexed" tabindex="-1">What gets indexed <a class="header-anchor" href="#what-gets-indexed" aria-label="Permalink to “What gets indexed”">​</a></h2><ul><li><strong>Monitored folders</strong>: The plugin registers the configured local folders with the host index service. Initial and incremental discovery is performed through the SDK&#39;s indexed directory enumeration and debounced directory-change notifications; each folder must be covered by a host local-drive or folder index, otherwise enumeration returns no files. Environment variables such as <code>%USERPROFILE%</code> and shell virtual paths such as <code>shell:Downloads</code> are supported when they resolve to a real folder.</li><li><strong>File extensions</strong>: The default list includes <code>txt</code>, <code>md</code>, <code>pdf</code>, <code>docx</code>, <code>docm</code>, <code>pptx</code>, <code>pptm</code>, <code>xlsx</code>, <code>xlsm</code>, and <code>csv</code>. You can change the comma-separated list to suit your files.</li><li><strong>PDF files</strong>: Searchable page text and saved values from fillable PDF form fields are included.</li><li><strong>File size</strong>: Files larger than the configured per-file limit are skipped. The content index also has a separate size cap; set it to <code>0</code> for unlimited size.</li><li><strong>Excluded paths</strong>: Add semicolon-separated regular expressions to exclude matching full paths. A match on a folder also excludes its contents.</li></ul><p>Files are only searched after their text has been extracted successfully. Binary files without a suitable document extractor are skipped instead of being indexed as unreadable text.</p><p>Document extraction has additional safety limits even when the configured file-size limit is unlimited: each decompressed Office ZIP entry is limited to 128 MiB and extracted Office/PDF text to 32 Mi characters per document. Documents exceeding a limit fail extraction instead of being partially indexed; individual extraction or write failures are logged and do not stop later files.</p><h2 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to “Searching”">​</a></h2><p>Type <code>cs</code> followed by a space and your keywords in the Quick Search Window. Matching files are shown with a text snippet and their containing folder; press <code>Enter</code> to open the selected file. When the query has results, the same file results are also available in the full search window when no type filter is active.</p><p>While the index is being built, the <code>cs</code> placeholder shows the number of indexed files and any remaining work. New and changed directories are reported by the host watcher and processed in the background, so regular filename search remains available during indexing. The plugin does not run a recurring filesystem scan after indexing has settled.</p><p>One- and two-character terms are supported, including queries that combine short and longer terms. Short terms are checked as literal substrings; use a longer term where possible for faster searches.</p><p>Completion is announced once after the initial content index and once after each explicit rebuild. Copying or editing files, saving settings, and restarting the app do not produce further completion notices. A size-cap pause has a separate warning; stopping or pausing indexing does not count as completion.</p><h2 id="clearing-and-rebuilding" tabindex="-1">Clearing and rebuilding <a class="header-anchor" href="#clearing-and-rebuilding" aria-label="Permalink to “Clearing and rebuilding”">​</a></h2><p>The Content Search settings provide two separate actions:</p><ul><li><strong>Clear Index</strong> removes the content index without scanning the monitored files again.</li><li><strong>Rebuild Index</strong> removes the content index and scans all monitored files again.</li></ul><p>These actions affect only the Content Search index; Lertaro&#39;s normal filename index is not removed.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>If a file does not appear, check its folder, extension, exclusion patterns, and size limit in the plugin settings.</li><li>If you change the monitored folders or indexing rules, save the settings and allow the background scan to complete.</li><li>Use <strong>Rebuild Index</strong> after changing rules when you want existing files to be extracted again.</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};